/* The link page's jogging runner (cut-out pieces, joints and run-cycle rig), shared so other tools can draw him.
   Copied verbatim from river-run/index.html, which keeps its own inline copy. */
(function () {
  'use strict';
  // prettier-ignore
        var IMGSRC={"head":"data:image/webp;base64,","torso":"data:image/webp;base64,","shorts":"data:image/webp;base64,","thigh":"data:image/webp;base64,","shin":"data:image/webp;base64,","shoe":"data:image/webp;base64,","upperarm":"data:image/webp;base64,","forearm":"data:image/webp;base64,","forearm_far":"data:image/webp;base64,"};
        /* Joints for each cut-out piece, in the source drawing's pixels (the link page rig). */
        // prettier-ignore
        var PARTS={"upperarm":{"pivot":[49,48],"end":[54,248]},"forearm":{"pivot":[34,36],"end":[43,221]},"thigh":{"pivot":[91.94999999999999,73.50000000000003],"end":[98.25,327.6]},"shin":{"pivot":[56,40],"end":[44,280]},"shoe":{"pivot":[55,26],"end":[211,26],"sole":[[-45,83],[55,91],[145,78],[156,58]]},"shorts":{"pivot":[94.94999999999999,95.50000000000003],"waist":[-3.1499999999999773,-71.50000000000001]},"torso":{"pivot":[108,346],"neck":[47,-338],"shoulder":[-25,-288]},"head":{"pivot":[90,195]}};

        // ---------- the rig: the link page's runner (jointed cut-out, run-cycle keyframes, jump pose)
        function makePuppet(imgs, parts, opt) {
          opt = opt || {};
          var R = Math.PI / 180;
          function sub(a, b) {
            return [a[0] - b[0], a[1] - b[1]];
          }
          function ang(v) {
            return Math.atan2(v[0], v[1]) / R;
          }
          function len(v) {
            return Math.hypot(v[0], v[1]);
          }
          function rot(v, a) {
            var c = Math.cos(a * R),
              s = Math.sin(a * R);
            return [v[0] * c - v[1] * s, v[0] * s + v[1] * c];
          }
          function bone(n) {
            var p = parts[n];
            return {
              rest: ang(sub(p.end, p.pivot)),
              len: len(sub(p.end, p.pivot)),
            };
          }
          var TH = bone('thigh'),
            SN = bone('shin'),
            UA = bone('upperarm'),
            FA = bone('forearm');
          var SHOE_SCALE = opt.shoeScale || 0.85,
            LEAN = opt.lean || 6;
          var FAR_SH = opt.farShoulder || [10, 4],
            FAR_HIP = opt.farHip || [10, -6];
          var HIP = [28, 14, 0, -20, -27, -12, 18, 38];
          var KNEE = [12, 38, 22, 10, 42, 100, 106, 72];
          var PF = [4, -24, -22, 10, 28, 18, 2, -18]; // ankle: + = toes pointed, - = toes pulled up
          var ARM = [-44, -34, -12, 14, 28, 20, 0, -26];
          var ELB = [80, 82, 86, 92, 96, 92, 86, 82];
          function cr(k, p) {
            var n = k.length,
              x = (((p % 1) + 1) % 1) * n,
              i = Math.floor(x),
              t = x - i,
              a = k[(i - 1 + n) % n],
              b = k[i % n],
              c = k[(i + 1) % n],
              d = k[(i + 2) % n];
            return (
              0.5 *
              (2 * b +
                (-a + c) * t +
                (2 * a - 5 * b + 4 * c - d) * t * t +
                (-a + 3 * b - 3 * c + d) * t * t * t)
            );
          }
          function pt(o, l, a) {
            return [o[0] + l * Math.sin(a * R), o[1] + l * Math.cos(a * R)];
          }
          var sole = parts.shoe.sole.map(function (q) {
            return [q[0] * SHOE_SCALE, q[1] * SHOE_SCALE];
          });
          // Jump state, set by the scene: tuck (0..1 knees up in the air), crouch (0..1 bent knees on the ground),
          // lift (source px above the ground), w (0..1 how much the jump overrides the stride's own hip height).
          var J = { tuck: 0, crouch: 0, lift: 0, w: 0, pump: 0 };
          function mixv(a, b, t) {
            return a + (b - a) * t;
          }
          function leg(p, h) {
            var hip = cr(HIP, p),
              kn = cr(KNEE, p),
              pf = cr(PF, p);
            if (J.tuck > 0) {
              var T = Math.PI * 2;
              hip = mixv(hip, 40 + 10 * Math.cos(T * p), J.tuck);
              kn = mixv(kn, 108, J.tuck);
              pf = mixv(pf, 32, J.tuck);
            }
            if (J.crouch > 0) {
              hip += 14 * J.crouch;
              kn += 34 * J.crouch;
            }
            var shin = hip - kn,
              foot = -shin + pf,
              k = pt(h, TH.len, hip),
              an = pt(k, SN.len, shin),
              low = -1e9;
            sole.forEach(function (q) {
              var r = rot(q, foot);
              low = Math.max(low, an[1] + r[1]);
            });
            return { hip: hip, shin: shin, foot: foot, k: k, an: an, low: low };
          }
          function lift(p) {
            var u = ((p % 0.5) + 0.5) % 0.5;
            return u > 0.34 && u < 0.5
              ? 22 * Math.sin((Math.PI * (u - 0.34)) / 0.16)
              : 0;
          }
          var N = 240,
            ys = [];
          for (var i = 0; i < N; i++) {
            var p = i / N,
              a = leg(p, [0, 0]),
              b = leg(p + 0.5, FAR_HIP);
            ys.push(-Math.max(a.low, b.low) - lift(p));
          }
          function hipY(p) {
            var x = (((p % 1) + 1) % 1) * N,
              i = Math.floor(x),
              t = x - i;
            return ys[i % N] * (1 - t) + ys[(i + 1) % N] * t;
          }
          var groundSpeed =
            (leg(0.06, [0, 0]).an[0] - leg(0.31, [0, 0]).an[0]) / 0.25;
          var K = opt.imgScale || 1; // pieces are stored smaller than the source; joints stay in source units
          var darkCache = {};
          function dark(name) {
            if (darkCache[name]) return darkCache[name];
            var src = imgs[name],
              c = document.createElement('canvas');
            c.width = src.naturalWidth || src.width;
            c.height = src.naturalHeight || src.height;
            var x = c.getContext('2d');
            x.drawImage(src, 0, 0);
            x.globalCompositeOperation = 'source-atop';
            x.fillStyle = 'rgba(8,14,30,.32)';
            x.fillRect(0, 0, c.width, c.height);
            return (darkCache[name] = c);
          }
          function piece(ctx, name, at, angle, sc, shade) {
            var info = parts[name] || parts[name.replace('_far', '')];
            ctx.save();
            ctx.translate(at[0], at[1]);
            ctx.rotate(angle * R);
            if (sc) ctx.scale(sc, sc);
            ctx.scale(1 / K, 1 / K);
            ctx.drawImage(
              shade ? dark(name) : imgs[name],
              -info.pivot[0] * K,
              -info.pivot[1] * K,
            );
            ctx.restore();
          }
          function drawLeg(ctx, q, h, shade) {
            piece(ctx, 'shin', q.k, SN.rest - q.shin, 0, shade);
            piece(ctx, 'shoe', q.an, q.foot, SHOE_SCALE, shade);
            piece(ctx, 'thigh', h, TH.rest - q.hip, 0, shade);
          }
          function drawArm(ctx, sh, p, shade) {
            var sw = cr(ARM, p),
              el = cr(ELB, p);
            if (J.tuck > 0) {
              sw = mixv(sw, shade ? -20 : 58, J.tuck);
              el = mixv(el, shade ? 70 : 104, J.tuck);
            } // drive the near arm up, far arm back
            if (J.crouch > 0) {
              sw = mixv(sw, -30, J.crouch * 0.7);
            } // arms swing back to load
            if (J.pump > 0 && !shade) {
              sw = mixv(sw, 148, J.pump);
              el = mixv(el, 30, J.pump);
            } // milestone fist pump
            var fo = sw + el,
              e = pt(sh, UA.len, sw);
            piece(
              ctx,
              shade && imgs.forearm_far ? 'forearm_far' : 'forearm',
              e,
              FA.rest - fo,
              0,
              shade,
            );
            piece(ctx, 'upperarm', sh, UA.rest - sw, 0, shade);
          }
          // Core motion. q = step phase (two steps per cycle). Landing is near q=0.25 (the "down" pose).
          function core(p) {
            var T = Math.PI * 2,
              q = p * 2;
            return {
              pelvisTilt: 2.2 * Math.sin(T * (q - 0.05)), // pelvis rocks a little with each step
              pelvisShift: 4 * Math.cos(T * p), // near hip swings forward and back with the near leg
              torsoLean: LEAN + 2.4 * Math.sin(T * (q - 0.2)) + 12 * J.crouch, // leans in a bit more on push-off (and when crouching to jump)
              squash: 1 - 0.018 * Math.max(0, Math.cos(T * (q - 0.25))), // tiny compress on landing
              shoulderTwist: 7 * Math.sin(T * (p + 0.25)), // shoulders rotate against the hips
              headCounter: -0.75, // head undoes most of the torso rock
            };
          }
          function draw(ctx, p, x, groundY, scale) {
            ctx.save();
            ctx.translate(x, groundY);
            ctx.scale(scale, scale);
            var c = core(p),
              hy = hipY(p);
            if (J.w > 0) {
              var a = leg(p, [0, 0]),
                b = leg(p + 0.5, FAR_HIP),
                ground = -Math.max(a.low, b.low);
              hy = mixv(hy, ground, J.w) - J.lift;
            }
            var h = [0, hy];
            // chain: hip -> waist (on the shorts) -> neck/shoulder (on the torso)
            var w = rot(parts.shorts.waist, c.pelvisTilt),
              waist = [h[0] + w[0], h[1] + w[1]];
            var tA = c.torsoLean;
            function onTorso(v) {
              var r = rot([v[0], v[1] * c.squash], tA);
              return [waist[0] + r[0], waist[1] + r[1]];
            }
            var neck = onTorso(parts.torso.neck),
              shBase = onTorso(parts.torso.shoulder);
            var sh = [shBase[0] + c.shoulderTwist, shBase[1]],
              fs = [
                shBase[0] + FAR_SH[0] - c.shoulderTwist,
                shBase[1] + FAR_SH[1],
              ];
            var nh = [h[0] + c.pelvisShift * 0.5, h[1]],
              fh = [h[0] + FAR_HIP[0] - c.pelvisShift * 0.5, h[1] + FAR_HIP[1]];
            var nq = leg(p, nh),
              fq = leg(p + 0.5, fh);
            drawArm(ctx, fs, p + 0.5, true);
            drawLeg(ctx, fq, fh, true);
            drawLeg(ctx, nq, nh, false);
            piece(ctx, 'shorts', h, c.pelvisTilt);
            piece(
              ctx,
              'head',
              neck,
              LEAN * 0.3 + (tA - LEAN) * (1 + c.headCounter),
            );
            ctx.save();
            ctx.translate(waist[0], waist[1]);
            ctx.rotate(tA * R);
            ctx.scale(1 / K, c.squash / K);
            ctx.drawImage(
              imgs.torso,
              -parts.torso.pivot[0] * K,
              -parts.torso.pivot[1] * K,
            );
            ctx.restore();
            drawArm(ctx, sh, p, false);
            ctx.restore();
          }
          return {
            draw: draw,
            groundSpeed: groundSpeed,
            leg: leg,
            hipY: hipY,
            jump: J,
          };
        }
  var cache = null;
  // Loads the pieces once; resolves with a ready puppet (pieces stored at half size, joints in source units).
  function load() {
    if (cache) return cache;
    cache = new Promise(function (resolve) {
      var imgs = {},
        names = Object.keys(IMGSRC),
        left = names.length;
      names.forEach(function (n) {
        var im = new Image();
        im.onload = im.onerror = function () {
          if (--left === 0) resolve(makePuppet(imgs, PARTS, { imgScale: 0.5 }));
        };
        im.src = IMGSRC[n];
        imgs[n] = im;
      });
    });
    return cache;
  }
  // The rig is about 1140 source units from head to sole.
  window.TimRunner = { load: load, height: 1140, makePuppet: makePuppet };
})();
